function draw() {
  ctx.clearRect(0, 0, width, height);
  // Ship (blue triangle rocket)
  ctx.fillStyle = '#00f';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.size / 2);
  ctx.lineTo(ship.x + ship.size, ship.y);
  ctx.lineTo(ship.x + ship.size, ship.y + ship.size);
  ctx.closePath();
  ctx.fill();
  // Asteroids (gray circles)
  ctx.fillStyle = '#777';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  // Score display
  ctx.fillStyle = '#000';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}s`, 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#fff';
    ctx.textAlign = 'center';
    ctx.font = '24px sans-serif';
    ctx.fillText(`Game Over – ${score}s`, width / 2, height / 2);
  }
}

input.newString:
function draw() {
  // background gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#001d3d');
  bgGrad.addColorStop(1, '#000814');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  // stars
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  // Ship (blue triangle rocket)
  ctx.fillStyle = '#00f';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.size / 2);
  ctx.lineTo(ship.x + ship.size, ship.y);
  ctx.lineTo(ship.x + ship.size, ship.y + ship.size);
  ctx.closePath();
  ctx.fill();
  // Asteroids (gray circles with subtle gradient)
  for (const a of asteroids) {
    const grad = ctx.createRadialGradient(a.x, a.y, a.radius * 0.2, a.x, a.y, a.radius);
    grad.addColorStop(0, '#aaa');
    grad.addColorStop(1, '#555');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  // Score display
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${score}s`, 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#ff0';
    ctx.textAlign = 'center';
    ctx.font = '24px sans-serif';
    ctx.fillText(`Game Over – ${score}s`, width / 2, height / 2);
  }
}

